$root=dirname(__DIR__,2);spl_autoload_register(function($c)use($root){if(strpos($c,'app\\')!==0)return;$f=$root.'/src/core/application/'.str_replace('\\','/',substr($c,4)).'.php';if(file_exists($f))require_once $f;});
require_once $root.'/src/core/application/common/dns/Huawei.php';require_once $root.'/src/core/application/common/dns/Baidu.php';require_once $root.'/src/core/application/common/dns/West.php';
$base='http://127.0.0.1:18982';$cases=array('huawei'=>array('class'=>'app\\common\\dns\\Huawei','endpoint'=>$base.'/huawei','config'=>array('access_key'=>'AKIDEXAMPLE','secret_key'=>'secret')),'baidu'=>array('class'=>'app\\common\\dns\\Baidu','endpoint'=>$base.'/baidu','config'=>array('access_key'=>'ak','secret_key'=>'sk')),'west'=>array('class'=>'app\\common\\dns\\West','endpoint'=>$base.'/west','config'=>array('username'=>'user','api_password'=>'pass')));$all=true;foreach($cases as $name=>$c){$cfg=$c['config'];$cfg['endpoint']=$c['endpoint'];try{$d=new $c['class']($cfg);$z=$d->getDomains();$pass=count($z)>0&&$z[0]['domain']==='example.com';echo $name.' '.($pass?'PASS':'FAIL')." domains\n";if(!$pass)$all=false;}catch(Exception $e){echo $name.' FAIL '.$e->getMessage()."\n";$all=false;}}exit($all?0:1);
